parameters.jsCode:
const item = $input.item.json;

function normalizePhone(raw) {
  if (!raw) return '';
  let digits = String(raw).replace(/[^\d+]/g, '');
  if (!digits.startsWith('+')) {
    // No country code given — assume a 10-digit local number is US/CA.
    // Adjust this default for your primary market.
    digits = digits.length === 10 ? `+1${digits}` : `+${digits}`;
  }
  return digits;
}

const email = (item.Email || '').trim().toLowerCase();
const phone = normalizePhone(item['Phone / WhatsApp Number'] || item.Phone || item.WhatsApp || '');
const isValidPhone = /^\+\d{8,15}$/.test(phone);

return {
  json: {
    lead_name: (item.Name || '').trim(),
    company: (item.Company || '').trim(),
    role: (item.Role || '').trim(),
    email: email,
    inquiry_message: (item['Inquiry Message'] || '').trim(),
    whatsapp_number: phone,
    is_valid_phone: isValidPhone,
    dedupe_key: `${email}|${phone}`,
    submitted_at: new Date().toISOString()
  }
};

